import{_ as t,o as e,c as l,a2 as r}from"./chunks/framework.1lR7qgqY.js";const p=JSON.parse('{"title":"作業程序範例: 新進同仁設備設定","description":"","frontmatter":{},"headers":[],"relativePath":"examples/procedure.md","filePath":"examples/procedure.md","lastUpdated":null}'),d={name:"examples/procedure.md"};function i(o,a,h,n,s,c){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="作業程序範例-新進同仁設備設定" tabindex="-1">作業程序範例: 新進同仁設備設定 <a class="header-anchor" href="#作業程序範例-新進同仁設備設定" aria-label="Permalink to &quot;作業程序範例: 新進同仁設備設定&quot;">​</a></h1><p>本頁示範標準作業程序 (SOP) 的寫法: 先寫目的與適用範圍, 再依順序列出步驟, 最後附檢核清單. 內容僅為示意, 正式使用時請替換.</p><h2 id="目的與適用範圍" tabindex="-1">目的與適用範圍 <a class="header-anchor" href="#目的與適用範圍" aria-label="Permalink to &quot;目的與適用範圍&quot;">​</a></h2><p>本程序說明新進同仁到職第一天的筆電設定步驟, 適用於所有到職同仁.</p><table tabindex="0"><thead><tr><th>項目</th><th>內容</th></tr></thead><tbody><tr><td>負責人</td><td>IT 管理員</td></tr><tr><td>所需時間</td><td>約 1 小時</td></tr><tr><td>前置條件</td><td>已建立公司帳號</td></tr></tbody></table><h2 id="作業步驟" tabindex="-1">作業步驟 <a class="header-anchor" href="#作業步驟" aria-label="Permalink to &quot;作業步驟&quot;">​</a></h2><h3 id="步驟-1-開機與登入" tabindex="-1">步驟 1: 開機與登入 <a class="header-anchor" href="#步驟-1-開機與登入" aria-label="Permalink to &quot;步驟 1: 開機與登入&quot;">​</a></h3><ol><li>開啟筆電, 依畫面指示選擇語言與地區.</li><li>使用公司帳號登入.</li><li>首次登入時, 依指示設定新密碼.</li></ol><h3 id="步驟-2-啟用磁碟加密" tabindex="-1">步驟 2: 啟用磁碟加密 <a class="header-anchor" href="#步驟-2-啟用磁碟加密" aria-label="Permalink to &quot;步驟 2: 啟用磁碟加密&quot;">​</a></h3><ol><li>開啟系統設定, 找到磁碟加密功能.</li><li>啟用加密, 並將復原金鑰交給 IT 管理員保管.</li></ol><div class="warning custom-block"><p class="custom-block-title">復原金鑰不可自行保存</p><p>復原金鑰遺失會導致資料無法復原, 必須由 IT 管理員統一保管.</p></div><h3 id="步驟-3-安裝必要軟體" tabindex="-1">步驟 3: 安裝必要軟體 <a class="header-anchor" href="#步驟-3-安裝必要軟體" aria-label="Permalink to &quot;步驟 3: 安裝必要軟體&quot;">​</a></h3><p>依職務別安裝軟體, 清單請洽 IT 管理員.</p><h3 id="步驟-4-設定多因素驗證" tabindex="-1">步驟 4: 設定多因素驗證 <a class="header-anchor" href="#步驟-4-設定多因素驗證" aria-label="Permalink to &quot;步驟 4: 設定多因素驗證&quot;">​</a></h3><ol><li>在手機安裝驗證 App.</li><li>登入帳號設定頁面, 掃描 QR Code 完成綁定.</li></ol><h2 id="完成檢核清單" tabindex="-1">完成檢核清單 <a class="header-anchor" href="#完成檢核清單" aria-label="Permalink to &quot;完成檢核清單&quot;">​</a></h2><ul><li>[ ] 已用公司帳號登入</li><li>[ ] 磁碟加密已啟用, 復原金鑰已交付</li><li>[ ] 必要軟體已安裝</li><li>[ ] 多因素驗證已綁定</li></ul><h2 id="修訂紀錄" tabindex="-1">修訂紀錄 <a class="header-anchor" href="#修訂紀錄" aria-label="Permalink to &quot;修訂紀錄&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>日期</th><th>修訂內容</th></tr></thead><tbody><tr><td>1.0</td><td>2026-10-26</td><td>初版</td></tr></tbody></table>',19)])])}const b=t(d,[["render",i]]);export{p as __pageData,b as default};
